import type { TT } from "../content";
const D: Record<string, TT> = {
  "qr-code-generator": ["Generador de códigos QR con logo", "Crea un código QR descargable para cualquier enlace o texto, con logo opcional.", "Generador de códigos QR gratis con logo. Crea al instante un QR descargable para cualquier URL o texto, sin registro.", "Un código QR permite abrir un enlace, ver un texto o conectarse a una red Wi-Fi con solo apuntar la cámara del móvil. Este generador crea un QR de alta resolución a partir de cualquier texto o URL y te deja poner tu propio logo en el centro.\n\nEs útil para quien añade QR a material impreso y envases, para restaurantes que enlazan su carta, para organizadores de eventos y para pequeños negocios que conectan el papel con su web o sus redes.\n\nEscribe o pega la URL o el texto y la vista previa se actualiza al momento. Elige los colores, ajusta el nivel de corrección de errores (más alto si añades un logo) y descarga el resultado en PNG.", [["¿Puedo añadir mi logo al código QR?", "Sí. Sube una imagen y se colocará en el centro con corrección de errores alta para que siga siendo legible."], ["¿Caduca el código QR?", "No. El código solo contiene el texto o la URL que indicas y funciona siempre, mientras funcione el destino."], ["¿Sirve para Wi-Fi o contactos?", "Sí. Puedes codificar cualquier texto, incluidos los formatos de Wi-Fi o vCard que los móviles reconocen."], ["¿Se envían mis datos a un servidor?", "No. El código se genera por completo en tu navegador."]]],
  "merge-pdf": ["Unir PDF (combinar varios PDF)", "Combina varios archivos PDF en un solo documento, en el orden que elijas.", "Combina varios archivos PDF en un solo documento, en el orden que elijas.", "Sube varios PDF, ordénalos y descarga un único documento. Todo ocurre en tu navegador, así que tus archivos no se suben a ningún servidor.\n\nSirve para juntar contratos, facturas, apuntes o escaneos en un solo archivo fácil de enviar. Arrastra los archivos para cambiar el orden antes de unirlos.", [["¿Se suben mis PDF a un servidor?", "No. La unión se hace en tu navegador y los archivos nunca salen de tu dispositivo."], ["¿Hay límite de archivos?", "No hay límite fijo. El máximo práctico depende de la memoria de tu dispositivo."], ["¿Puedo cambiar el orden?", "Sí, reordena los archivos antes de unirlos."]]],
  "split-pdf": ["Dividir PDF página por página", "Divide un PDF en páginas sueltas o en rangos de páginas personalizados.", "Divide un PDF en páginas sueltas o en rangos de páginas personalizados.", "Sube un PDF y elige cómo dividirlo: cada página por separado o los rangos que indiques, por ejemplo 1-3, 5. Funciona en tu navegador, sin subir el archivo.\n\nEs útil para extraer un capítulo, enviar solo las páginas necesarias o separar un escaneo con varios documentos. Recibirás los resultados en un ZIP.", [["¿Puedo extraer solo algunas páginas?", "Sí, escribe los rangos que necesites, como 1-3, 5, 8-10."], ["¿Cómo descargo varias páginas?", "Se agrupan en un archivo ZIP."], ["¿Se sube mi PDF?", "No, todo se procesa en tu navegador."]]],
  "pdf-compressor": ["Compresor de PDF", "Reduce el tamaño de un PDF recomprimiendo las imágenes de sus páginas.", "Reduce el tamaño de un PDF recomprimiendo las imágenes de sus páginas.", "Sube un PDF, elige el nivel de compresión y descarga una versión más ligera. Funciona en tu navegador y el archivo no se sube a ningún sitio.\n\nUn PDF más pequeño es más fácil de enviar por correo o de subir a formularios con límite de tamaño. El método convierte cada página en imagen, así que el texto deja de ser seleccionable.", [["¿Se pierde calidad?", "Algo, según el nivel elegido. Prueba primero el nivel medio."], ["¿Seguirá el texto seleccionable?", "No. Las páginas se guardan como imágenes comprimidas."], ["¿Se sube mi archivo?", "No, todo se hace en tu navegador."]]],
  "jpg-to-pdf": ["Convertir JPG a PDF", "Une una o varias imágenes JPG en un único PDF descargable.", "Une una o varias imágenes JPG en un único PDF descargable.", "Sube tus fotos JPG, ordénalas y descarga un solo PDF. Todo se hace en tu navegador, sin subir las imágenes.\n\nSirve para convertir fotos de documentos, recibos o apuntes en un PDF fácil de enviar. El orden de las imágenes es el orden de las páginas.", [["¿Puedo juntar varias imágenes en un PDF?", "Sí, cada imagen será una página."], ["¿Se suben mis fotos?", "No, la conversión ocurre en tu navegador."], ["¿Cambia la calidad de las imágenes?", "Se conservan tal cual, solo se colocan en las páginas."]]],
  "pdf-to-jpg": ["Convertir PDF a JPG", "Convierte cada página de un PDF en una imagen JPG descargable.", "Convierte cada página de un PDF en una imagen JPG descargable.", "Sube un PDF y obtén una imagen JPG por página, en un ZIP. Funciona en tu navegador, sin subir el archivo.\n\nÚtil para compartir una página como imagen, subirla a redes sociales o insertarla en una presentación. Puedes elegir la calidad antes de convertir.", [["¿Obtengo una imagen por página?", "Sí, cada página se guarda como un JPG."], ["¿Se sube mi PDF?", "No, la conversión se hace en tu navegador."], ["¿Puedo elegir la calidad?", "Sí, ajusta la calidad antes de convertir."]]],
  "percentage-calculator": ["Calculadora de porcentajes: porcentaje de un número, aumento y descuento", "Calcula porcentajes, variación porcentual y qué porcentaje es una cifra de un total.", "Calculadora de porcentajes gratis con ejemplos resueltos. Calcula qué porcentaje es X de Y, aumentos, descuentos y el porcentaje de un número, por ejemplo 25/28 en porcentaje.", "Los porcentajes aparecen a diario: un descuento, una propina, una subida de sueldo o una estadística. La fórmula cambia según lo que quieras averiguar. Esta calculadora resuelve los tres casos más comunes: qué porcentaje es un número de otro, cuánto es un porcentaje de una cantidad y cuánto aumenta o disminuye un valor en porcentaje.\n\nElige el tipo de cálculo: \"¿Cuánto es X% de Y?\" (por ejemplo, el 20% de 150), \"X es qué porcentaje de Y?\" (por ejemplo, qué porcentaje es 30 de 120) o \"Variación porcentual de X a Y\" (por ejemplo, de 80 a 100). Escribe los números y el resultado aparece al instante con el cálculo detallado.\n\nUn error frecuente es creer que un aumento del 50% y una bajada del 50% se compensan. Si 100 sube un 50% llega a 150, pero si 150 baja un 50% queda en 75, no en 100, porque cada porcentaje se calcula sobre su propio valor de partida. Tampoco hay que confundir puntos porcentuales con variación porcentual: pasar de un 20% a un 25% de interés son 5 puntos porcentuales, pero un aumento relativo del 25%. Y dos descuentos seguidos no se suman: un 20% y luego un 10% dan un 28% en total, no un 30%.\n\nEjemplos resueltos que puedes comprobar con la calculadora:\n- ¿Cuánto es el 15% de 200? 200 × 0,15 = 30.\n- ¿Cuánto es el 20% de 85? 85 × 0,20 = 17.\n- 25 es qué porcentaje de 28? 25 ÷ 28 × 100 = 89,29 %, así que 25/28 en porcentaje es aproximadamente 89,3 %.\n- 30 es qué porcentaje de 120? 30 ÷ 120 × 100 = 25 %.\n- Aumento porcentual de 80 a 100: (100 − 80) ÷ 80 × 100 = 25 %.\n- Disminución porcentual de 50 a 40: (50 − 40) ÷ 50 × 100 = 20 %.\n- Diferencia porcentual entre 40 y 60 (respecto a su media, 50): 20 ÷ 50 × 100 = 40 %.\n\nFórmulas: parte ÷ total × 100 da el porcentaje. El porcentaje de un número es número × porcentaje ÷ 100. La variación porcentual es (nuevo − antiguo) ÷ antiguo × 100. Para convertir una fracción como 25/28 en porcentaje, divide el numerador entre el denominador y multiplica por 100.", [["¿Por qué un aumento del 50% y una bajada del 50% no devuelven el número original?", "Porque cada variación se calcula sobre el valor actual en ese momento, no sobre el valor inicial. Por eso el resultado no es simétrico."], ["¿Qué diferencia hay entre puntos porcentuales y variación porcentual?", "Los puntos porcentuales miden la diferencia absoluta entre dos porcentajes (de 20% a 25% son 5 puntos). La variación porcentual mide la diferencia relativa (un aumento del 25%)."], ["¿Los descuentos sucesivos se suman directamente?", "No. Un descuento del 20% seguido de otro del 10% da un 28% en total, no un 30%, porque el segundo se aplica sobre el precio ya rebajado."], ["¿Sirve para calcular una propina?", "Sí. Usa \"¿cuánto es X% de Y?\" con el total de la cuenta y el porcentaje de propina que quieras dejar."], ["¿Se envían mis datos a un servidor?", "No. Todos los cálculos se hacen al instante en tu navegador."], ["¿Cómo calculo 25/28 en porcentaje?", "Divide 25 entre 28 y multiplica por 100. El resultado es aproximadamente 89,29 %."], ["¿Cómo calculo un aumento porcentual?", "Resta el valor antiguo al nuevo, divide entre el valor antiguo y multiplica por 100. De 80 a 100 es un aumento del 25%."], ["¿Cómo sé qué porcentaje es un número de otro?", "Divide la parte entre el total y multiplica por 100. Por ejemplo, 30 es el 25% de 120."], ["¿Cuál es la fórmula de la diferencia porcentual?", "Divide la diferencia absoluta entre la media de los dos números y multiplica por 100. Para 40 y 60 el resultado es 40%."]]],
  "age-calculator": ["Calculadora de edad: edad exacta en años, meses y días", "Calcula tu edad exacta en años, meses y días a partir de la fecha de nacimiento.", "Calculadora de edad gratis. Obtén tu edad exacta en años, meses y días a partir de tu fecha de nacimiento, los días vividos o tu edad en cualquier fecha.", "Calcular la edad exacta, en años, meses y días y no solo en años, exige tener en cuenta la distinta duración de los meses y los años bisiestos. Restar a mano es más delicado de lo que parece. Esta calculadora obtiene al instante la edad exacta, o el tiempo transcurrido entre dos fechas cualesquiera.\n\nIntroduce una fecha de nacimiento (o cualquier fecha de inicio) y, si quieres, una fecha \"a fecha de\" (por defecto, hoy). La herramienta muestra la edad en años, meses y días, además del total de días y de semanas vividos y del día de la semana en que naciste.\n\nCómo se cuenta la edad exacta: primero se restan los años, después los meses y por último los días, tomando prestados los días del mes anterior cuando hace falta. Por eso alguien nacido el 31 de enero tiene un número de días distinto el 28 de febrero que el 31 de marzo. Quienes nacieron el 29 de febrero se cuentan con la duración real de cada mes.\n\nUn error habitual es restar el año de nacimiento al año actual. Si tu cumpleaños aún no ha llegado este año, el resultado sale un año de más. Esta herramienta tiene en cuenta el mes y el día, no solo el año.\n\nUsos habituales: comprobar la edad exacta en meses de un niño para un formulario, confirmar si se cumple una edad mínima en una fecha concreta (pon como \"a fecha de\" el plazo límite), saber cuántos días tienes y calcular la diferencia de edad entre dos personas, poniendo la fecha de nacimiento de una como inicio y la de la otra como \"a fecha de\".\n\nReferencia rápida: un año no bisiesto tiene 365 días (52 semanas y 1 día) y uno bisiesto, 366. Una persona de 30 años ha vivido unos 10 950 días más 7 u 8 días bisiestos.", [["¿Tiene en cuenta los años bisiestos?", "Sí. El cálculo tiene en cuenta los años bisiestos y la distinta duración de los meses al obtener la edad exacta."], ["¿Puedo calcular el tiempo entre dos fechas cualesquiera?", "Sí. Indica una fecha de inicio y una fecha final concreta para obtener la duración exacta entre ambas."], ["¿Por qué restar los años da un resultado incorrecto?", "Porque no considera si el cumpleaños ya ha pasado este año, así que el resultado puede salir un año de más según la fecha actual."], ["¿Muestra los días o semanas totales además de años, meses y días?", "Sí. Junto al desglose en años, meses y días se muestran los totales de días y semanas."], ["¿Se guarda mi fecha de nacimiento?", "No. El cálculo se hace al instante y de forma local en tu navegador. No se guarda ni se envía ningún dato personal."], ["¿Cómo calculo la diferencia de edad entre dos personas?", "Introduce la fecha de nacimiento de la persona mayor como fecha de inicio y la de la más joven como fecha \"a fecha de\". El resultado es la diferencia en años, meses y días."], ["¿Cómo averiguo mi edad en una fecha concreta?", "Introduce tu fecha de nacimiento y pon en \"a fecha de\" la fecha que necesitas, como el plazo de una solicitud o un evento."], ["¿Cuántos días tengo?", "Introduce tu fecha de nacimiento. La herramienta muestra los días vividos junto al desglose en años, meses y días."], ["¿Cómo se tratan los nacidos el 29 de febrero?", "El cálculo usa la duración real de cada mes, así que una fecha de nacimiento del 29 de febrero se cuenta según el calendario real."]]],
  "bmi-calculator": ["Calculadora de IMC (índice de masa corporal)", "Calcula tu índice de masa corporal a partir de la estatura y el peso.", "Calculadora de IMC gratis. Calcula tu índice de masa corporal al instante a partir de tu estatura y peso, en unidades métricas o imperiales.", "El índice de masa corporal (IMC) es una medida de cribado muy usada que estima si el peso de una persona está en un rango saludable en relación con su estatura. Se calcula con una fórmula sencilla a partir de dos datos. Esta calculadora obtiene tu IMC al instante y muestra en qué categoría estándar se encuentra, con unidades métricas o imperiales.\n\nElige unidades métricas (kilogramos y centímetros) o imperiales (libras y pulgadas o pies), escribe tu estatura y tu peso y el IMC se calcula con la fórmula estándar: peso en kilogramos dividido entre la estatura en metros al cuadrado. El resultado se muestra junto a las categorías de la Organización Mundial de la Salud: bajo peso, peso normal, sobrepeso y obesidad.\n\nPor ejemplo, una persona de 170 cm que pesa 65 kg tiene un IMC de aproximadamente 22,5, dentro del rango de peso normal (18,5–24,9) según la OMS.\n\nEs importante conocer sus límites: el IMC es una herramienta de cribado poblacional, no un diagnóstico individual. No distingue entre masa muscular y grasa, así que personas muy musculosas, como deportistas, pueden salir con sobrepeso u obesidad aunque tengan poca grasa y buena salud. Tampoco tiene en cuenta la edad, el sexo, la densidad ósea ni dónde se acumula la grasa. Úsalo como una referencia general y consulta tu situación con un profesional sanitario.\n\nConsejo: si eres deportista, muy musculoso, estás embarazada, eres una persona mayor o te sales del grupo de población en el que se basa el IMC, interpreta el resultado con más cautela y da prioridad a otros indicadores, como la composición corporal, la forma física y los análisis de sangre, que puedes comentar con un profesional.", [["¿Es el IMC una medida exacta de la salud individual?", "Es una herramienta útil de cribado poblacional, pero no tiene en cuenta la masa muscular, la composición corporal, la edad ni la distribución de la grasa. Consulta siempre tu caso con un profesional sanitario."], ["¿Por qué un deportista puede tener un IMC alto estando sano?", "Porque el músculo es más denso que la grasa: las personas muy musculosas pesan más para su estatura y obtienen un IMC mayor aunque tengan poca grasa y buena salud."], ["¿Cuáles son las categorías estándar del IMC?", "Bajo peso (menos de 18,5), peso normal (18,5-24,9), sobrepeso (25-29,9) y obesidad (30 o más), según la clasificación de la OMS."], ["¿Se aplica igual a los niños?", "No. En niños y adolescentes se usan tablas de percentiles de IMC por edad y sexo, no las categorías de adultos de esta herramienta."], ["¿Se guardan mis datos de salud?", "No. El cálculo se hace al instante y de forma local en tu navegador. No se guarda ni se envía nada."]]],
  "loan-emi-calculator": ["Calculadora de cuota de préstamo (EMI)", "Calcula tu cuota mensual, el interés total y el coste total de cualquier préstamo.", "Calcula la cuota mensual de un préstamo (EMI), el interés total y el coste total según el importe, el tipo de interés y el plazo.", "La cuota EMI (cuota mensual fija) es el importe fijo que pagas cada mes hasta devolver el préstamo. Incluye intereses y una parte del capital. Introduce el importe del préstamo, el tipo de interés anual y el plazo en años, y la calculadora muestra tu cuota mensual, el total que devolverás y el total de intereses.\n\nLa fórmula es EMI = P × r × (1 + r)^n / ((1 + r)^n − 1), donde P es el capital, r es el tipo mensual (el tipo anual dividido entre 12 y entre 100) y n es el número de cuotas mensuales. Las primeras cuotas son sobre todo intereses y la parte de capital va creciendo con el tiempo.\n\nÚsala para comparar ofertas de préstamo, para ver cómo un plazo más largo baja la cuota pero aumenta el interés total, o para comprobar qué cuota puedes asumir. No incluye comisiones bancarias, seguros ni tipos variables, así que el resultado es una estimación: confirma la cifra final con tu entidad.", [["¿Cómo se calcula la cuota EMI?", "EMI = P × r × (1 + r)^n / ((1 + r)^n − 1), con P el importe del préstamo, r el tipo de interés mensual y n el número de meses."], ["¿Un plazo más largo reduce mi cuota?", "Sí, la cuota mensual baja, pero pagas más intereses en total porque el capital pendiente tarda más en amortizarse."], ["¿Incluye comisiones o seguros?", "No. Solo incluye capital e intereses. Añade por separado las comisiones de apertura y los seguros."], ["¿Se envían mis datos a un servidor?", "No. Todo se ejecuta en tu navegador. Nada de lo que escribes se sube ni se guarda."]]],
  "aspect-ratio-calculator": ["Calculadora de relación de aspecto (16:9, 4:3 y más)", "Calcula dimensiones proporcionales para cualquier relación de aspecto.", "Calculadora de relación de aspecto gratis. Calcula el ancho y el alto proporcionales para 16:9, 4:3, 1:1 y proporciones personalizadas al instante.", "Mantener la relación de aspecto correcta al cambiar el tamaño de una imagen, un vídeo o un elemento de diseño evita estiramientos y deformaciones. Calcularla a mano con una regla de tres es fácil de hacer mal con prisas. Esta calculadora obtiene al instante el ancho o el alto que falta para una relación dada, o la relación simplificada a partir de dos dimensiones.\n\nSirve para editores de vídeo y creadores de contenido que preparan proyectos en 16:9 o 9:16, para diseñadores que redimensionan imágenes sin perder proporciones y para desarrolladores que calculan contenedores adaptables con una relación concreta.\n\nElige una proporción predefinida (16:9, 4:3, 1:1, 3:2, 21:9) o escribe una personalizada, e introduce un ancho o un alto conocido: la calculadora muestra la otra dimensión. También puedes introducir dos dimensiones para obtener y simplificar su relación real.\n\nPor ejemplo, si necesitas un fotograma 16:9 de 1920 px de ancho, la altura correcta es 1080 px. Y si introduces 2560×1440 en el cálculo inverso, se simplifica a 16:9, la misma proporción panorámica que 1920×1080 pero con más resolución.\n\nUn error habitual es redimensionar a ojo, lo que suele provocar un estiramiento sutil que el espectador nota aunque no sepa explicar por qué algo \"se ve raro\".\n\nConsejo: para maquetaciones web adaptables que deban mantener una proporción (por ejemplo, un contenedor de vídeo 16:9), usa la propiedad CSS aspect-ratio (aspect-ratio: 16 / 9) en lugar de los antiguos trucos con padding en porcentaje: es más simple y más legible.", [["¿Cómo calculo la altura si solo conozco el ancho y la relación deseada?", "Elige o escribe la relación, introduce el ancho conocido y la calculadora obtiene al instante la altura exacta."], ["¿Puedo saber la relación de aspecto de unas dimensiones que ya tengo?", "Sí. Introduce el ancho y el alto en el cálculo inverso para obtener la relación simplificada. Por ejemplo, 2560×1440 se simplifica a 16:9."], ["¿Cuáles son las relaciones de aspecto más habituales?", "16:9 (vídeo panorámico), 4:3 (formato antiguo de TV y fotografía), 1:1 (cuadrado, común en redes sociales), 9:16 (formato vertical o de historias) y 21:9 (ultrapanorámico de cine)."], ["¿Por qué importa mantener la relación de aspecto?", "Si cambias el tamaño sin mantenerla, el contenido se estira o se aplasta, algo que suele notarse y resulta poco profesional."], ["¿Puedo usar el resultado directamente en CSS?", "Sí. Usa la relación calculada con la propiedad CSS aspect-ratio para imponer proporciones de forma limpia en diseños adaptables."]]],
  "mortgage-calculator": ["Calculadora de hipoteca", "Estima tu cuota hipotecaria mensual con capital, intereses, impuestos de la propiedad y seguro del hogar.", "Estima tu cuota hipotecaria mensual con capital, intereses, impuestos de la propiedad y seguro del hogar.", "Una cuota hipotecaria tiene cuatro partes: capital, intereses, impuesto de la propiedad y seguro del hogar. Esta calculadora toma el precio de la vivienda, tu entrada, el tipo de interés y el plazo, suma los impuestos y el seguro anuales y muestra el coste mensual total y los intereses totales durante la vida del préstamo.\n\nUna entrada mayor reduce el importe del préstamo y los intereses que pagas. Un plazo más corto, como 15 años en lugar de 30, sube la cuota mensual pero recorta mucho los intereses totales. Prueba varias combinaciones para ver la diferencia.\n\nEl resultado es una estimación. Las entidades pueden añadir un seguro hipotecario si la entrada es pequeña, cuotas de comunidad, o cambiar el tipo. Úsalo para planificar y pide después una oferta oficial.", [["¿Qué precio de vivienda puedo permitirme?", "Una guía habitual es no superar el 28% de los ingresos brutos mensuales en gastos de vivienda. Prueba con distintos precios para ver cuánto sale la cuota."], ["¿Qué incluye la cuota?", "Capital e intereses, más el impuesto de la propiedad y el seguro anuales que introduzcas, divididos entre 12."], ["¿Incluye el seguro hipotecario (PMI)?", "No. Si tu entidad lo exige, súmalo en el campo del seguro."], ["¿Se envían mis datos a un servidor?", "No. Todo se ejecuta en tu navegador. Nada de lo que escribes se sube ni se guarda."]]],
  "compound-interest-calculator": ["Calculadora de interés compuesto", "Mira cómo crecen tus ahorros o inversiones con interés compuesto y aportaciones mensuales.", "Mira cómo crecen tus ahorros o inversiones con interés compuesto y aportaciones mensuales.", "El interés compuesto significa que ganas intereses sobre los intereses anteriores, y no solo sobre la cantidad inicial. A largo plazo, este efecto de bola de nieve es la razón principal por la que conviene empezar pronto. Introduce un importe inicial, una aportación mensual, un tipo anual y el número de años.\n\nLa calculadora aplica la frecuencia de capitalización que elijas (anual, trimestral, mensual o diaria) y suma tus aportaciones cada mes. Muestra el saldo final, cuánto has aportado y cuánto procede de los intereses.\n\nLa rentabilidad real varía cada año y las comisiones y los impuestos la reducen, así que usa un tipo prudente para planificar. El resultado es una proyección, no una garantía.", [["¿Cuál es la fórmula del interés compuesto?", "A = P(1 + r/n)^(nt) para un único depósito, donde P es el capital, r el tipo anual, n los periodos de capitalización por año y t los años."], ["¿Importa que la capitalización sea más frecuente?", "Un poco. La capitalización diaria rinde algo más que la anual al mismo tipo, pero el tipo y el tiempo importan mucho más."], ["¿Incluye impuestos y comisiones?", "No. Resta las comisiones e impuestos previstos a tu tipo para obtener una estimación más realista."], ["¿Se envían mis datos a un servidor?", "No. Todo se ejecuta en tu navegador. Nada de lo que escribes se sube ni se guarda."]]],
  "simple-interest-calculator": ["Calculadora de interés simple", "Calcula el interés simple y el importe total para un capital, un tipo anual y un número de años.", "Calcula el interés simple y el importe total para un capital, un tipo anual y un número de años.", "El interés simple se cobra solo sobre el capital inicial, no sobre los intereses ya generados. La fórmula es I = P × r × t, donde P es el capital, r es el tipo anual en forma decimal y t es el tiempo en años.\n\nSe usa en préstamos a corto plazo, algunos préstamos de coche, bonos y ejercicios escolares. Introduce el capital, el tipo anual y los años y obtendrás el interés y el importe total que debes o que ganas.\n\nSi los intereses se suman al saldo y generan a su vez intereses, usa mejor la calculadora de interés compuesto.", [["¿Cuál es la fórmula del interés simple?", "I = P × r × t. Importe total = P + I."], ["¿En qué se diferencia del interés compuesto?", "El interés compuesto también genera intereses sobre los intereses pasados, por lo que crece más rápido a largo plazo."], ["¿Se envían mis datos a un servidor?", "No. Todo se ejecuta en tu navegador. Nada de lo que escribes se sube ni se guarda."]]],
  "tip-calculator": ["Calculadora de propinas", "Calcula la propina y divide la cuenta entre amigos. Introduce la cuenta, el porcentaje y el número de personas.", "Calcula la propina y divide la cuenta entre amigos. Introduce la cuenta, el porcentaje y el número de personas.", "Introduce el total de la cuenta, elige un porcentaje de propina y el número de personas que pagan, y la calculadora muestra la propina, el total y lo que paga cada uno.\n\nLas propinas habituales son del 15% al 20% en Estados Unidos y Canadá. En muchos otros países el servicio ya está incluido o la propina es pequeña, así que mira primero la cuenta.\n\nPara calcular la propina sobre el importe sin impuestos, introduce la cuenta sin impuestos. Redondear a una cifra cómoda por persona está bien entre amigos.", [["¿Cuánta propina debo dejar?", "En EE. UU. es habitual dejar del 15% al 20% en servicio de mesa. Las costumbres cambian según el país."], ["¿La propina se calcula antes o después de impuestos?", "Mucha gente la calcula sobre el importe sin impuestos. Ambas opciones son aceptables."], ["¿Se envían mis datos a un servidor?", "No. Todo se ejecuta en tu navegador. Nada de lo que escribes se sube ni se guarda."]]],
  "vat-calculator": ["Calculadora de IVA e impuesto sobre ventas", "Suma o quita el IVA, el GST o el impuesto sobre ventas de cualquier precio. Obtén el neto, el impuesto y el bruto al instante.", "Suma o quita el IVA, el GST o el impuesto sobre ventas de cualquier precio. Obtén el neto, el impuesto y el bruto al instante.", "Elige si el importe ya incluye impuestos o no. Para añadir el impuesto, la calculadora multiplica el precio neto por (1 + tipo). Para quitarlo, divide el precio bruto entre (1 + tipo), lo cual no equivale a restar el porcentaje.\n\nIndica cualquier tipo: 14% (IVA de Egipto), 20% (Reino Unido), 19% (Alemania), 5% (Emiratos Árabes Unidos) o el impuesto sobre ventas de un estado de EE. UU. La herramienta muestra el importe neto, el impuesto y el total bruto.\n\nComprueba siempre el tipo que corresponde a tu producto y país, ya que algunos bienes tienen tipos reducidos o del 0%.", [["¿Cómo quito el IVA de un precio?", "Divide el precio bruto entre 1 + el tipo. Con un 20%, divide entre 1,2."], ["¿Por qué no basta con restar el 20% del precio?", "Porque el impuesto se añadió sobre el precio neto, así que es el 20% del neto y no del bruto."], ["¿Se envían mis datos a un servidor?", "No. Todo se ejecuta en tu navegador. Nada de lo que escribes se sube ni se guarda."]]],
  "hourly-to-salary-calculator": ["Calculadora de salario por hora a sueldo anual", "Convierte un salario por hora en pago anual, mensual, semanal y diario.", "Convierte un salario por hora en pago anual, mensual, semanal y diario.", "Introduce tu tarifa por hora, las horas que trabajas por semana y las semanas que trabajas al año. La calculadora las multiplica para obtener tu pago bruto anual y luego lo divide para mostrar los importes mensual, semanal y diario.\n\nUn trabajo a tiempo completo de 40 horas durante 52 semanas son 2080 horas al año. Resta las semanas sin sueldo si te tomas tiempo libre no remunerado.\n\nSon importes brutos, antes de impuestos y deducciones. Lo que cobras realmente será menor.", [["¿Cuántas horas de trabajo hay en un año?", "Unas 2080 con una semana de 40 horas y 52 semanas."], ["¿El resultado es antes o después de impuestos?", "Antes de impuestos. Es tu pago bruto."], ["¿Se envían mis datos a un servidor?", "No. Todo se ejecuta en tu navegador. Nada de lo que escribes se sube ni se guarda."]]],
  "days-between-dates-calculator": ["Calculadora de días entre fechas", "Cuenta los días, semanas, meses y días laborables entre dos fechas.", "Cuenta los días, semanas, meses y días laborables entre dos fechas.", "Elige una fecha de inicio y una de fin y la calculadora devuelve el número de días entre ambas, el mismo periodo en semanas, en años, meses y días, y el número de días laborables (de lunes a viernes).\n\nÚsala para contar los días que faltan para un evento, calcular un preaviso, comprobar cuánto duró un proyecto o conocer tu antigüedad. El orden de las fechas no importa.\n\nLos festivos no se excluyen del recuento de días laborables.", [["¿Incluye la fecha final?", "Cuenta la diferencia, así que no se cuenta la fecha final. Suma un día si necesitas incluir ambas."], ["¿Cómo se cuentan los meses?", "Por meses naturales y después los días restantes."], ["¿Se envían mis datos a un servidor?", "No. Todo se ejecuta en tu navegador. Nada de lo que escribes se sube ni se guarda."]]],
  "date-calculator": ["Calculadora de fechas: sumar o restar días, semanas y meses", "Suma o resta días, semanas, meses o años a cualquier fecha.", "Suma o resta días, semanas, meses o años a cualquier fecha.", "Elige una fecha de inicio, decide si sumar o restar, introduce una cantidad y una unidad, y la calculadora muestra la fecha resultante con su día de la semana.\n\nTiene en cuenta la duración de los meses y los años bisiestos. Úsala para plazos, fechas de entrega, garantías y periodos de prueba.\n\nNo se omiten los días laborables ni los festivos.", [["¿Qué fecha es dentro de 90 días?", "Pon la fecha de inicio en hoy, elige Sumar, escribe 90 y la unidad Días."], ["¿Tiene en cuenta los años bisiestos?", "Sí, usa el calendario de tu navegador."], ["¿Se envían mis datos a un servidor?", "No. Todo se ejecuta en tu navegador. Nada de lo que escribes se sube ni se guarda."]]],
  "calorie-calculator": ["Calculadora de calorías (TMB y GET)", "Estima tus calorías diarias para mantener, perder o ganar peso con la ecuación de Mifflin-St Jeor.", "Estima tus calorías diarias para mantener, perder o ganar peso con la ecuación de Mifflin-St Jeor.", "Tu tasa metabólica basal (TMB) es la energía que tu cuerpo gasta en reposo. Al multiplicarla por un factor de actividad se obtiene tu gasto energético total diario (GET), que es aproximadamente las calorías que necesitas para mantener el peso.\n\nEsta herramienta usa la ecuación de Mifflin-St Jeor. Introduce sexo, edad, estatura, peso y nivel de actividad. Un déficit de unas 500 calorías al día suele traducirse en perder aproximadamente 0,5 kg por semana, y un superávit de 500 en ganarlos.\n\nEs una estimación y no un consejo médico. No bajes de las ingestas mínimas seguras sin asesoramiento profesional.", [["¿Qué es la TMB?", "Las calorías que tu cuerpo gasta en reposo para mantenerte vivo."], ["¿Qué precisión tiene?", "Se acerca a un 10% en la mayoría de los adultos. Controla tu peso durante dos semanas y ajusta."], ["¿Se envían mis datos a un servidor?", "No. Todo se ejecuta en tu navegador. Nada de lo que escribes se sube ni se guarda."]]],
  "ideal-weight-calculator": ["Calculadora de peso ideal", "Estima tu peso corporal ideal según la estatura y el sexo, con el rango de IMC saludable.", "Estima tu peso corporal ideal según la estatura y el sexo, con el rango de IMC saludable.", "Introduce tu estatura y sexo para ver las estimaciones de peso ideal según las fórmulas de Devine y Robinson, además del rango de peso que corresponde a un IMC saludable de 18,5 a 24,9.\n\nEstas fórmulas dan una referencia aproximada. La masa muscular, la estructura ósea y la edad cambian lo que es saludable para cada persona.\n\nUsa el rango de IMC como guía más amplia y consulta a un médico para un consejo personal.", [["¿Qué fórmula es la mejor?", "Ninguna es perfecta. El rango de IMC es una guía más amplia que una cifra única."], ["¿Es fiable el IMC para deportistas?", "No. El músculo pesa más que la grasa, así que un deportista puede tener un IMC alto y estar sano."], ["¿Se envían mis datos a un servidor?", "No. Todo se ejecuta en tu navegador. Nada de lo que escribes se sube ni se guarda."]]],
  "roi-calculator": ["Calculadora de ROI (retorno de la inversión)", "Calcula el retorno de la inversión, el beneficio y la rentabilidad anualizada de cualquier inversión.", "Calcula el retorno de la inversión, el beneficio y la rentabilidad anualizada de cualquier inversión.", "El ROI es el beneficio de una inversión dividido entre su coste, expresado en porcentaje. Introduce lo que invertiste y el valor final, y la calculadora muestra el beneficio y el ROI. Si añades cuántos años mantuviste la inversión, también muestra la rentabilidad anualizada.\n\nROI = (valor final − coste) / coste × 100. La rentabilidad anualizada (CAGR) permite comparar dos inversiones con periodos de tenencia distintos.\n\nRecuerda que las comisiones, los impuestos y la inflación reducen tu rentabilidad real.", [["¿Qué es un buen ROI?", "Depende del activo y del riesgo. La rentabilidad a largo plazo de la bolsa ronda de media entre el 7% y el 10% anual antes de inflación."], ["¿Qué diferencia hay entre ROI y CAGR?", "El ROI es el retorno total. El CAGR es la tasa anual que lo produciría."], ["¿Se envían mis datos a un servidor?", "No. Todo se ejecuta en tu navegador. Nada de lo que escribes se sube ni se guarda."]]],
  "cagr-calculator": ["Calculadora de CAGR (tasa de crecimiento anual compuesto)", "Calcula la tasa de crecimiento anual compuesto a partir de un valor inicial, uno final y el número de años.", "Calcula la tasa de crecimiento anual compuesto a partir de un valor inicial, uno final y el número de años.", "El CAGR es la tasa de crecimiento anual constante que llevaría un valor desde su inicio hasta su final durante un periodo. La fórmula es (final / inicial)^(1 / años) − 1.\n\nSuaviza los altibajos para que puedas comparar con justicia inversiones, ingresos o crecimiento de usuarios en periodos distintos.\n\nEl CAGR no muestra la volatilidad. Dos inversiones pueden tener el mismo CAGR y un riesgo muy distinto.", [["¿Cómo calculo el CAGR?", "Divide el valor final entre el inicial, elévalo a 1 dividido entre los años y resta 1."], ["¿Puede ser negativo el CAGR?", "Sí, si el valor final es menor que el inicial."], ["¿Se envían mis datos a un servidor?", "No. Todo se ejecuta en tu navegador. Nada de lo que escribes se sube ni se guarda."]]],
  "percentage-increase-calculator": ["Calculadora de aumento y disminución porcentual", "Calcula el aumento o la disminución porcentual entre dos números.", "Calcula el aumento o la disminución porcentual entre dos números.", "Introduce el valor antiguo y el nuevo para obtener la variación porcentual. Un resultado positivo es un aumento y uno negativo es una disminución. La fórmula es (nuevo − antiguo) / antiguo × 100.\n\nLa herramienta también muestra la diferencia porcentual simétrica, que divide entre la media de los dos valores. Úsala cuando ninguno de los dos sea claramente el punto de partida.\n\nUn aumento del 50% seguido de una disminución del 50% no vuelve al inicio, porque cada porcentaje se aplica sobre una base distinta.", [["¿Cómo calculo la variación porcentual?", "(nuevo − antiguo) / antiguo × 100."], ["¿Qué es la diferencia porcentual?", "La diferencia entre dos valores dividida entre su media, que se usa cuando no hay una base de referencia."], ["¿Se envían mis datos a un servidor?", "No. Todo se ejecuta en tu navegador. Nada de lo que escribes se sube ni se guarda."]]],
  "speed-distance-time-calculator": ["Calculadora de velocidad, distancia y tiempo", "Calcula la velocidad a partir de la distancia y el tiempo, en km/h, mph y ritmo de carrera.", "Calcula la velocidad a partir de la distancia y el tiempo, en km/h, mph y ritmo de carrera.", "La velocidad es la distancia dividida entre el tiempo. Introduce una distancia en kilómetros y un tiempo en horas para obtener la velocidad media en km/h y mph, además de tu ritmo en minutos por kilómetro.\n\nPara hallar la distancia, multiplica la velocidad por el tiempo. Para hallar el tiempo, divide la distancia entre la velocidad. Usa horas decimales: 1 hora y 30 minutos es 1,5.\n\nPara los corredores, el ritmo es la cifra que conviene comparar. Para los conductores, la velocidad media ayuda a estimar la hora de llegada.", [["¿Cómo paso minutos a horas?", "Divide entre 60. 45 minutos son 0,75 horas."], ["¿Qué es el ritmo?", "El tiempo que se tarda en recorrer un kilómetro o una milla."], ["¿Se envían mis datos a un servidor?", "No. Todo se ejecuta en tu navegador. Nada de lo que escribes se sube ni se guarda."]]],
  "pregnancy-due-date-calculator": ["Calculadora de fecha probable de parto", "Estima tu fecha de parto y de concepción a partir del primer día de tu última regla.", "Estima tu fecha de parto y de concepción a partir del primer día de tu última regla.", "Introduce el primer día de tu última menstruación y la duración habitual de tu ciclo. La calculadora suma 280 días (regla de Naegele), ajustados a la duración del ciclo, para estimar la fecha de parto, y muestra una fecha aproximada de concepción y tu semana actual.\n\nSolo alrededor del 5% de los bebés nace en su fecha prevista. La mayoría llega entre las semanas 37 y 42. Una ecografía temprana da la datación más precisa.\n\nEsta herramienta es solo informativa. Sigue las indicaciones de tu médico o matrona.", [["¿Cómo se calcula la fecha de parto?", "280 días (40 semanas) después del primer día de la última regla."], ["¿Es precisa?", "Es una estimación. La datación por ecografía es más precisa."], ["¿Se envían mis datos a un servidor?", "No. Todo se ejecuta en tu navegador. Nada de lo que escribes se sube ni se guarda."]]],
  "fraction-calculator": ["Calculadora de fracciones", "Suma, resta, multiplica y divide fracciones. Obtén la fracción simplificada, el número mixto y el decimal.", "Suma, resta, multiplica y divide fracciones. Obtén la fracción simplificada, el número mixto y el decimal.", "Introduce dos fracciones y elige una operación. La calculadora busca un denominador común cuando hace falta, simplifica el resultado con el máximo común divisor y lo muestra como fracción, número mixto y decimal.\n\nPara sumar o restar, los denominadores deben coincidir, así que primero se convierte cada fracción. Para multiplicar, se multiplican numeradores y denominadores. Para dividir, se multiplica por la inversa de la segunda fracción.\n\nÚsala para revisar deberes, recetas y medidas.", [["¿Cómo sumo fracciones?", "Busca un denominador común, suma los numeradores y simplifica."], ["¿Cómo divido fracciones?", "Da la vuelta a la segunda fracción y multiplica."], ["¿Se envían mis datos a un servidor?", "No. Todo se ejecuta en tu navegador. Nada de lo que escribes se sube ni se guarda."]]],
  "average-calculator": ["Calculadora de promedio (media, mediana y moda)", "Pega una lista de números y obtén la media, la mediana, la moda, la suma, el rango y la desviación típica.", "Pega una lista de números y obtén la media, la mediana, la moda, la suma, el rango y la desviación típica.", "Pega o escribe números separados por comas, espacios o saltos de línea. La calculadora muestra la cantidad, la suma, la media (promedio), la mediana (valor central), la moda (valor más frecuente), el mínimo, el máximo y la desviación típica muestral.\n\nLa media es la suma dividida entre la cantidad. La mediana se ve menos afectada por los valores extremos, por lo que es mejor para ingresos o precios. La desviación típica indica cuán dispersos están los números.\n\nLas entradas no numéricas se ignoran.", [["¿Qué diferencia hay entre media y mediana?", "La media es el promedio aritmético. La mediana es el valor central al ordenar los datos."], ["¿La desviación típica es muestral o poblacional?", "Muestral (divide entre n − 1)."], ["¿Se envían mis datos a un servidor?", "No. Todo se ejecuta en tu navegador. Nada de lo que escribes se sube ni se guarda."]]],
  "random-number-generator": ["Generador de números aleatorios", "Genera números aleatorios en cualquier rango, con o sin repetición, con la fuente aleatoria segura de tu navegador.", "Genera números aleatorios en cualquier rango, con o sin repetición, con la fuente aleatoria segura de tu navegador.", "Fija un mínimo y un máximo, elige cuántos números quieres y pulsa Generar. Marca Sin repetir para sacar números únicos, como las bolas de una lotería.\n\nLos números proceden del generador aleatorio criptográfico del navegador, adecuado para juegos, sorteos y muestreos.\n\nPara sorteos oficiales o claves de seguridad, sigue las normas de tu organización.", [["¿Es realmente aleatorio?", "Usa crypto.getRandomValues, una fuente criptográficamente fuerte."], ["¿Puedo obtener números únicos?", "Sí, marca Sin repetir."], ["¿Se envían mis datos a un servidor?", "No. Todo se ejecuta en tu navegador. Nada de lo que escribes se sube ni se guarda."]]],
  "dice-roller": ["Lanzador de dados y cara o cruz", "Lanza dados virtuales (d4 a d100) o echa una moneda. Justo, instantáneo y apto para móviles.", "Lanza dados virtuales (d4 a d100) o echa una moneda. Justo, instantáneo y apto para móviles.", "Elige cuántos dados y cuántas caras, y lanza. La herramienta muestra cada dado y el total. Admite d4, d6, d8, d10, d12, d20 y d100 para juegos de mesa y de rol.\n\nEl botón de la moneda da cara o cruz con la misma probabilidad.\n\nLas tiradas usan una fuente aleatoria segura y no se guardan.", [["¿Son justas las tiradas?", "Sí, cada cara tiene la misma probabilidad."], ["¿Puedo lanzar más de un dado?", "Sí, hasta 50 a la vez."], ["¿Se envían mis datos a un servidor?", "No. Todo se ejecuta en tu navegador. Nada de lo que escribes se sube ni se guarda."]]],
  "random-name-picker": ["Selector aleatorio de nombres", "Elige un ganador al azar de una lista de nombres o mezcla la lista. Ideal para sorteos, clases y equipos.", "Elige un ganador al azar de una lista de nombres o mezcla la lista. Ideal para sorteos, clases y equipos.", "Pega un nombre o elemento por línea. Pulsa Elegir un ganador para seleccionar uno al azar, o Mezclar para aleatorizar el orden de la lista, útil para formar equipos o decidir el orden de presentaciones.\n\nUsa una fuente aleatoria segura, así que cada entrada tiene la misma probabilidad.\n\nEn sorteos públicos, graba la pantalla mientras eliges para que los participantes puedan verificar el resultado.", [["¿Es justa la elección?", "Sí, cada línea tiene la misma probabilidad."], ["¿Puedo elegir más de uno?", "Pulsa Elegir de nuevo, o usa Mezclar y toma los primeros nombres."], ["¿Se envían mis datos a un servidor?", "No. Todo se ejecuta en tu navegador. Nada de lo que escribes se sube ni se guarda."]]],
  "stopwatch": ["Cronómetro online", "Un cronómetro online sencillo con tiempos parciales. Funciona en tu navegador, sin instalar nada.", "Un cronómetro online sencillo con tiempos parciales. Funciona en tu navegador, sin instalar nada.", "Pulsa Iniciar para empezar a medir y Pausa para detenerte. Pulsa Vuelta para registrar tiempos parciales mientras el cronómetro sigue en marcha y Reiniciar para borrarlo todo.\n\nEl tiempo se mide con el reloj del sistema, así que se mantiene preciso incluso si la pestaña va lenta en segundo plano.\n\nMantén la página abierta mientras cronometras.", [["¿Qué precisión tiene?", "Hasta una centésima de segundo, limitada por tu dispositivo."], ["¿Sigue funcionando si cambio de pestaña?", "Sí, se recalcula con el reloj cuando vuelves."], ["¿Se envían mis datos a un servidor?", "No. Todo se ejecuta en tu navegador. Nada de lo que escribes se sube ni se guarda."]]],
  "countdown-timer": ["Temporizador de cuenta atrás online", "Fija una cuenta atrás en minutos. Suena al acabar y muestra el tiempo en el título de la pestaña.", "Fija una cuenta atrás en minutos. Suena al acabar y muestra el tiempo en el título de la pestaña.", "Introduce los minutos y pulsa Iniciar. El tiempo restante aparece en dígitos grandes y en el título de la pestaña del navegador, para que puedas trabajar en otra pestaña. Al terminar suena un pitido corto.\n\nÚsalo para cocinar, entrenar, presentaciones, exámenes y sesiones de estudio.\n\nMantén la pestaña abierta y el sonido activado.", [["¿Puedo pausar el temporizador?", "Sí, pulsa Pausa e Iniciar de nuevo para continuar."], ["¿Sonará si la pestaña está en segundo plano?", "Normalmente sí, pero algunos navegadores limitan el audio en segundo plano, así que mira el título de la pestaña."], ["¿Se envían mis datos a un servidor?", "No. Todo se ejecuta en tu navegador. Nada de lo que escribes se sube ni se guarda."]]],
  "pomodoro-timer": ["Temporizador Pomodoro", "Un temporizador Pomodoro con sesiones de concentración de 25 minutos y descansos de 5.", "Un temporizador Pomodoro con sesiones de concentración de 25 minutos y descansos de 5.", "La técnica Pomodoro divide el trabajo en sesiones de concentración de 25 minutos separadas por descansos de 5. Pulsa Iniciar para una sesión de concentración. Cuando termina suena un pitido y el temporizador pasa al descanso.\n\nTras cuatro sesiones, haz un descanso más largo de 15 a 30 minutos. Puedes cambiar los minutos en cualquier momento.\n\nElimina distracciones durante la sesión y apunta las tareas nuevas para atenderlas después.", [["¿Qué es la técnica Pomodoro?", "Un método de gestión del tiempo de Francesco Cirillo con bloques de trabajo de 25 minutos y descansos cortos."], ["¿Puedo cambiar la duración?", "Sí, edita el campo de minutos."], ["¿Se envían mis datos a un servidor?", "No. Todo se ejecuta en tu navegador. Nada de lo que escribes se sube ni se guarda."]]],
  "morse-code-translator": ["Traductor de código Morse", "Traduce texto a código Morse y código Morse a texto. Letras, números y puntuación habitual.", "Traduce texto a código Morse y código Morse a texto. Letras, números y puntuación habitual.", "Elige una dirección y escribe o pega tu texto. Las letras se convierten en puntos y rayas separados por espacios y las palabras se separan con una barra. Para descodificar, pega código Morse con espacios entre letras y una barra entre palabras.\n\nEl código Morse se creó para la comunicación telegráfica entre 1830 y 1840 y aún se usa en aviación, radioafición y como señal de emergencia. SOS son tres puntos, tres rayas, tres puntos.\n\nLos símbolos desconocidos se omiten al codificar y se muestran como un signo de interrogación al descodificar.", [["¿Cómo se escribe SOS en código Morse?", "... --- ..."], ["¿Cómo separo las palabras?", "Usa una barra inclinada entre palabras."], ["¿Se envían mis datos a un servidor?", "No. Todo se ejecuta en tu navegador. Nada de lo que escribes se sube ni se guarda."]]],
  "text-to-binary": ["Conversor de texto a binario", "Convierte texto a código binario y binario a texto. Compatible con Unicode mediante UTF-8.", "Convierte texto a código binario y binario a texto. Compatible con Unicode mediante UTF-8.", "Escribe texto y obtén su representación binaria, un byte de 8 bits por carácter en ASCII. Cambia el modo para descodificar una cadena binaria a texto legible.\n\nEl texto se codifica en UTF-8, así que las letras con acento, el árabe y los emojis también funcionan, usando varios bytes por carácter.\n\nSepara los bytes con espacios al descodificar.", [["¿Cuál es el binario de la letra A?", "01000001."], ["¿Admite árabe o emojis?", "Sí, mediante UTF-8."], ["¿Se envían mis datos a un servidor?", "No. Todo se ejecuta en tu navegador. Nada de lo que escribes se sube ni se guarda."]]],
  "roman-numeral-converter": ["Conversor de números romanos", "Convierte números a números romanos y números romanos a números (de 1 a 3999).", "Convierte números a números romanos y números romanos a números (de 1 a 3999).", "Escribe un número del 1 al 3999 para obtener el número romano, o escribe un número romano para obtener el número. La herramienta usa las reglas sustractivas estándar, como IV para 4 y CM para 900.\n\nLos números romanos usan las letras I, V, X, L, C, D y M para 1, 5, 10, 50, 100, 500 y 1000.\n\nLos números superiores a 3999 no tienen una forma estándar sin notación ampliada.", [["¿Cuál es 2026 en números romanos?", "MMXXVI."], ["¿Por qué el límite es 3999?", "Los números romanos estándar no tienen un símbolo superior a M, y MMMM no se usa."], ["¿Se envían mis datos a un servidor?", "No. Todo se ejecuta en tu navegador. Nada de lo que escribes se sube ni se guarda."]]],
  "number-to-words-converter": ["Conversor de números a palabras (en inglés)", "Convierte números a palabras en inglés, para cheques, facturas y redacción. Admite decimales y negativos.", "Convierte números a palabras en inglés, para cheques, facturas y redacción. Admite decimales y negativos.", "Introduce un número como 1234.56 y obtén las palabras en inglés: one thousand, two hundred and thirty-four point five six. Admite números de hasta billones, negativos y decimales.\n\nEscribir los importes con palabras es habitual en cheques, contratos y facturas para evitar alteraciones.\n\nLa ortografía sigue el estilo británico, con and después de las centenas.", [["¿Qué tamaño de número puedo convertir?", "Hasta 999 billones (trillion en inglés)."], ["¿Admite decimales?", "Sí. Los decimales se leen dígito a dígito."], ["¿Se envían mis datos a un servidor?", "No. Todo se ejecuta en tu navegador. Nada de lo que escribes se sube ni se guarda."]]],
  "text-repeater": ["Repetidor de texto", "Repite cualquier texto o emoji muchas veces con un separador personalizado.", "Repite cualquier texto o emoji muchas veces con un separador personalizado.", "Introduce tu texto, elige cuántas veces repetirlo y selecciona un separador. Usa \\n para un salto de línea. El resultado se copia con un clic.\n\nEs útil para datos de prueba, patrones, rellenar marcadores de posición y publicaciones en redes.\n\nEl límite es de 10 000 repeticiones para que tu navegador siga respondiendo.", [["¿Cuál es el máximo?", "10 000 repeticiones."], ["¿Puedo repetir en líneas nuevas?", "Sí, usa \\n como separador."], ["¿Se envían mis datos a un servidor?", "No. Todo se ejecuta en tu navegador. Nada de lo que escribes se sube ni se guarda."]]],
  "remove-punctuation": ["Quitar la puntuación de un texto", "Elimina la puntuación y los símbolos de cualquier texto con un clic. Funciona con muchos idiomas.", "Elimina la puntuación y los símbolos de cualquier texto con un clic. Funciona con muchos idiomas.", "Pega tu texto y se eliminan todos los signos de puntuación y símbolos, dejando letras, números y espacios. Funciona con Unicode, así que se conservan las letras con acento y no latinas.\n\nEs útil para limpiar texto antes de un análisis, un recuento de palabras, una investigación de palabras clave o aprendizaje automático.\n\nLos espacios repetidos se reducen a uno.", [["¿Elimina los apóstrofos?", "Sí, toda la puntuación, incluidos los apóstrofos."], ["¿Conserva las letras con acento?", "Sí."], ["¿Se envían mis datos a un servidor?", "No. Todo se ejecuta en tu navegador. Nada de lo que escribes se sube ni se guarda."]]],
  "upside-down-text-generator": ["Generador de texto al revés", "Voltea tu texto al revés con caracteres Unicode especiales. Copia y pega donde quieras.", "Voltea tu texto al revés con caracteres Unicode especiales. Copia y pega donde quieras.", "Escribe texto y mira cómo se voltea y se invierte con caracteres Unicode parecidos. El resultado puede pegarse en biografías de redes sociales, chats y publicaciones.\n\nFunciona porque Unicode contiene caracteres que se parecen a letras giradas. Algunos caracteres no tienen versión volteada y se quedan como están.\n\nEl aspecto depende de la fuente de la plataforma donde lo pegues.", [["¿Dónde puedo pegarlo?", "Casi en cualquier sitio que admita texto Unicode, como Instagram, X y WhatsApp."], ["¿Por qué algunas letras se ven distintas?", "No todas las letras tienen un gemelo Unicode girado exacto."], ["¿Se envían mis datos a un servidor?", "No. Todo se ejecuta en tu navegador. Nada de lo que escribes se sube ni se guarda."]]],
  "word-frequency-counter": ["Contador de frecuencia de palabras", "Cuenta cuántas veces aparece cada palabra en tu texto. Ordena por frecuencia y filtra por recuento mínimo.", "Cuenta cuántas veces aparece cada palabra en tu texto. Ordena por frecuencia y filtra por recuento mínimo.", "Pega tu texto y verás cada palabra con su recuento y porcentaje, ordenadas de más a menos frecuente. Fija un recuento mínimo para ocultar las palabras poco frecuentes.\n\nLos escritores lo usan para detectar palabras repetidas en exceso, los estudiantes para analizar textos y los equipos de SEO para revisar el uso de palabras clave.\n\nLa lista muestra hasta 100 palabras. Las palabras se pasan a minúsculas y se ignora la puntuación.", [["¿Se incluyen palabras comunes como \"the\"?", "Sí. Se cuentan todas las palabras."], ["¿Funciona en otros idiomas?", "Sí, admite letras Unicode."], ["¿Se envían mis datos a un servidor?", "No. Todo se ejecuta en tu navegador. Nada de lo que escribes se sube ni se guarda."]]],
  "readability-score-checker": ["Comprobador de legibilidad (Flesch)", "Comprueba lo fácil que es leer tu texto en inglés con la puntuación de facilidad de lectura de Flesch y el nivel escolar.", "Comprueba lo fácil que es leer tu texto en inglés con la puntuación de facilidad de lectura de Flesch y el nivel escolar.", "Pega tu texto para obtener la puntuación de facilidad de lectura de Flesch, un nivel escolar estimado de EE. UU., el recuento de palabras y frases y el tiempo de lectura.\n\nLas puntuaciones Flesch más altas indican textos más fáciles. Una puntuación de 60 a 70 corresponde a un inglés sencillo que entienden la mayoría de los adultos. Frases y palabras más cortas aumentan la puntuación.\n\nEl recuento de sílabas es aproximado para las palabras en inglés, así que toma el resultado como una guía.", [["¿Qué es una buena puntuación Flesch?", "De 60 a 70 es inglés sencillo estándar. El contenido web suele aspirar a 60 o más."], ["¿Funciona para árabe u otros idiomas?", "No. La fórmula es para inglés."], ["¿Se envían mis datos a un servidor?", "No. Todo se ejecuta en tu navegador. Nada de lo que escribes se sube ni se guarda."]]],
  "number-base-converter": ["Conversor de bases numéricas (binario, octal, decimal, hexadecimal)", "Convierte números entre binario, octal, decimal y hexadecimal.", "Convierte números entre binario, octal, decimal y hexadecimal.", "Introduce un número y elige su base. El conversor muestra el mismo valor en binario (base 2), octal (base 8), decimal (base 10) y hexadecimal (base 16). Admite números muy grandes mediante enteros grandes.\n\nLos programadores usan el hexadecimal para colores, direcciones de memoria y máscaras de bits, y el binario para ver los bits individuales.\n\nLos dígitos deben ser válidos para la base elegida, así que el 2 no es válido en binario.", [["¿Cómo paso de binario a decimal?", "Selecciona la base 2, introduce el número binario y lee el resultado en decimal."], ["¿El hexadecimal distingue mayúsculas de minúsculas?", "No."], ["¿Se envían mis datos a un servidor?", "No. Todo se ejecuta en tu navegador. Nada de lo que escribes se sube ni se guarda."]]],
  "json-minifier": ["Minificador de JSON", "Minifica JSON quitando espacios y saltos de línea. Valida tu JSON al mismo tiempo.", "Minifica JSON quitando espacios y saltos de línea. Valida tu JSON al mismo tiempo.", "Pega JSON con formato y obtén una versión compacta de una sola línea sin espacios innecesarios. Esto reduce el tamaño de las cargas útiles de API y de los archivos de configuración.\n\nLa herramienta analiza primero tu JSON, así que una entrada no válida muestra un error en lugar de producir una salida rota.\n\nMinificar no cambia los datos, solo su formato. Para lo contrario, usa el formateador de JSON.", [["¿Minificar cambia mis datos?", "No, solo se quitan los espacios."], ["¿Qué pasa si mi JSON no es válido?", "Verás un mensaje de error. Corrige primero la sintaxis."], ["¿Se envían mis datos a un servidor?", "No. Todo se ejecuta en tu navegador. Nada de lo que escribes se sube ni se guarda."]]],
  "sort-lines-alphabetically": ["Ordenar líneas alfabéticamente", "Ordena líneas de texto de A a Z, de Z a A, por número o longitud, invierte el orden o mézclalas.", "Ordena líneas de texto de A a Z, de Z a A, por número o longitud, invierte el orden o mézclalas.", "Pega una lista con un elemento por línea y elige un modo de orden: de A a Z, de Z a A, numérico, por longitud, invertido o mezcla aleatoria.\n\nEl orden alfabético usa una comparación adaptada al idioma, de modo que las letras con acento se ordenan con sentido. El orden numérico lee el número al comienzo de cada línea.\n\nÚsalo para nombres, palabras clave, URL, tareas pendientes y limpieza de datos.", [["¿Distingue mayúsculas de minúsculas?", "No, A y a se ordenan juntas."], ["¿Puedo ordenar números correctamente?", "Sí, elige Numérico para que el 10 vaya después del 9."], ["¿Se envían mis datos a un servidor?", "No. Todo se ejecuta en tu navegador. Nada de lo que escribes se sube ni se guarda."]]],
  "text-to-pdf": ["Conversor de texto a PDF", "Convierte texto sin formato en un PDF descargable desde tu navegador. Sin subir archivos ni registrarte.", "Convierte texto sin formato en un PDF descargable desde tu navegador. Sin subir archivos ni registrarte.", "Escribe o pega tu texto, elige un nombre de archivo y pulsa Descargar PDF. La herramienta distribuye el texto en páginas A4 con márgenes, ajusta las líneas largas y crea páginas nuevas automáticamente.\n\nEl PDF se crea dentro de tu navegador con una biblioteca de PDF, así que tu texto nunca se sube a un servidor.\n\nLa fuente estándar admite caracteres latinos. Otros alfabetos se sustituyen por signos de interrogación, así que usa un procesador de textos completo para árabe o chino.", [["¿Se sube mi texto?", "No. Se crea localmente."], ["¿Admite árabe?", "Todavía no. Solo caracteres latinos."], ["¿Se envían mis datos a un servidor?", "No. Todo se ejecuta en tu navegador. Nada de lo que escribes se sube ni se guarda."]]],
  "time-zone-converter": ["Conversor de zonas horarias", "Convierte una fecha y hora entre 25 zonas horarias principales a la vez.", "Convierte una fecha y hora entre 25 zonas horarias principales a la vez.", "Elige una fecha y hora, selecciona la zona horaria en la que está y verás el mismo momento en 25 zonas principales, como Nueva York, Londres, El Cairo, Dubái, Bombay, Tokio y Sídney.\n\nUsa la base de datos de zonas horarias de tu navegador, así que los cambios de horario de verano se tienen en cuenta para la fecha que elijas.\n\nÚsalo para programar reuniones y llamadas entre países.", [["¿Tiene en cuenta el horario de verano?", "Sí, para la fecha que elijas."], ["¿Puedo añadir más zonas?", "La lista cubre las más habituales."], ["¿Se envían mis datos a un servidor?", "No. Todo se ejecuta en tu navegador. Nada de lo que escribes se sube ni se guarda."]]],
};
export default D;
